CREATE TABLE public.workspace_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), kind text NOT NULL, data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.workspace_records TO authenticated;
GRANT ALL ON public.workspace_records TO service_role;
ALTER TABLE public.workspace_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_records ON public.workspace_records FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE INDEX workspace_records_user_kind ON public.workspace_records(user_id,kind);
CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, title text NOT NULL, company text NOT NULL, category text NOT NULL, location text NOT NULL DEFAULT 'Тараз', price numeric NOT NULL DEFAULT 0, unit text NOT NULL DEFAULT 'шт.', min_quantity integer NOT NULL DEFAULT 1, discount integer NOT NULL DEFAULT 0, description text NOT NULL DEFAULT '', image_key text NOT NULL DEFAULT 'grain', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.products TO authenticated;
GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalog_read ON public.products FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY catalog_insert ON public.products FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY catalog_update ON public.products FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK(user_id = auth.uid());
CREATE POLICY catalog_delete ON public.products FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL DEFAULT 'Новый диалог', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.threads TO authenticated;
GRANT ALL ON public.threads TO service_role;
ALTER TABLE public.threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_threads ON public.threads FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.chat_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), thread_id uuid NOT NULL REFERENCES public.threads(id) ON DELETE CASCADE, message_id text NOT NULL, message jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(thread_id,message_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.chat_messages TO authenticated;
GRANT ALL ON public.chat_messages TO service_role;
ALTER TABLE public.chat_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_chat_messages ON public.chat_messages FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND EXISTS(SELECT 1 FROM public.threads t WHERE t.id = thread_id AND t.user_id = auth.uid()));
CREATE INDEX chat_messages_thread ON public.chat_messages(thread_id,created_at);
CREATE TABLE public.b2b_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL DEFAULT auth.uid(), receiver_id uuid NOT NULL, product_id uuid REFERENCES public.products(id), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.b2b_messages TO authenticated;
GRANT ALL ON public.b2b_messages TO service_role;
ALTER TABLE public.b2b_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY participant_read ON public.b2b_messages FOR SELECT TO authenticated USING (sender_id = auth.uid() OR receiver_id = auth.uid());
CREATE POLICY sender_insert ON public.b2b_messages FOR INSERT TO authenticated WITH CHECK (sender_id = auth.uid());